BIB_MSG[biab.add.missing]='biab add: falta el nombre del grupo.\n'
BIB_MSG[biab.add.usage]='Uso: biab add <grupo>   (opcionales: %s)\n'
BIB_MSG[biab.add.core]=''\''%s'\'' es una skill básica: ya está instalada en todos los equipos.\n'
BIB_MSG[biab.add.unknown]='biab add: grupo '\''%s'\'' desconocido.\n'
