BIB_MSG[biab.status.title]='Builders in a Box: estado\n'
BIB_MSG[biab.status.usage]='uso: biab status [--json]\n'
BIB_MSG[biab.status.noservice]='Servicio de la app del teléfono: no instalado en este equipo (reintenta con: sudo biab update)\n'
BIB_MSG[biab.status.box]='Equipo: usuario %s, IA %s, perfil %s\n'
BIB_MSG[biab.status.notchosen]='aún sin elegir'
BIB_MSG[biab.status.done]='Pasos hechos: %s\n'
BIB_MSG[biab.status.none]='ninguno'
BIB_MSG[biab.status.notdone]='Pendientes: %s  (ejecuta: biab)\n'
BIB_MSG[biab.status.unreadable]='(no se pudo leer state.json)\n'
